SELECT COALESCE(string_agg(t.linha, E'\n' ORDER BY t.ordem), CASE WHEN $3::int >= 3 THEN 'nao encontrei nada com esse perfil. pergunte ao corretor se ele aceitaria um quarto a menos antes de encerrar' ELSE 'nao encontrei nada com esse perfil' END) AS texto_pronto, CASE WHEN count(*) = 0 THEN 'nao ha resultado. faca exatamente o que o texto_pronto manda e nada alem disso.' WHEN count(*) = 1 AND count(*) FILTER (WHERE t.acima) = 1 THEN 'ATENCAO: e uma unica opcao e ela custa MAIS do que o corretor pediu. Diga primeiro que nao tem nada dentro do valor dele, ofereca esta como alternativa citando o valor, e ja chame imovel_por_codigo e mande o imovel completo na mesma resposta. NAO pergunte qual codigo ele quer.' WHEN count(*) = 1 THEN 'ATENCAO: e uma unica opcao. NAO pergunte qual codigo ele quer. Chame imovel_por_codigo agora e mande o imovel completo na mesma resposta.' WHEN count(*) FILTER (WHERE t.acima) > 0 THEN 'ATENCAO: os itens marcados com (acima do teto) custam mais do que o corretor pediu. Avise isso com naturalidade antes da lista e depois pergunte qual codigo ele quer.' ELSE 'pergunte qual codigo ele quer receber' END AS instrucao_para_voce FROM (SELECT '• ' || i.codigo || ' — ' || CASE WHEN COALESCE(i.quartos,0) > 0 THEN i.quartos || CASE WHEN i.quartos = 1 THEN ' quarto' ELSE ' quartos' END || CASE WHEN COALESCE(i.suites,0) > 0 THEN ' sendo ' || i.suites || CASE WHEN i.suites = 1 THEN ' suíte' ELSE ' suítes' END ELSE '' END ELSE i.tipo END || CASE WHEN COALESCE(i.area_util,0) > 0 THEN ' — ' || trim(to_char(i.area_util,'FM999990')) || 'm2' ELSE '' END || ' — ' || CASE WHEN $2 = 'locacao' THEN 'locação ' || replace(to_char(i.valor_aluguel,'FM999,999,990'),',','.') ELSE replace(to_char(i.valor_venda,'FM999,999,990'),',','.') END || CASE WHEN COALESCE(i.mobilia,'') <> '' THEN ' — ' || replace(replace(i.mobilia,'moveis','móveis'),'so ar-condicionado','só ar-condicionado') ELSE '' END || CASE WHEN $4::numeric > 0 AND CASE WHEN $2 = 'locacao' THEN i.valor_aluguel ELSE i.valor_venda END > $4::numeric THEN ' (acima do teto)' ELSE '' END AS linha, CASE WHEN $2 = 'locacao' THEN i.valor_aluguel ELSE i.valor_venda END AS ordem, ($4::numeric > 0 AND CASE WHEN $2 = 'locacao' THEN i.valor_aluguel ELSE i.valor_venda END > $4::numeric) AS acima FROM imoveis i WHERE i.condominio_nome IN (SELECT nome FROM nay_cond($1)) AND i.disponivel = true AND COALESCE(i.bloqueado,false) = false AND COALESCE(i.e_parceiro,false) = false AND (($2 = 'locacao' AND COALESCE(i.valor_aluguel,0) > 0) OR ($2 = 'venda' AND COALESCE(i.valor_venda,0) > 0)) AND ($3::int = 0 OR i.quartos = $3::int) AND ($4::numeric = 0 OR CASE WHEN $2 = 'locacao' THEN i.valor_aluguel ELSE i.valor_venda END BETWEEN $4::numeric * 0.85 AND $4::numeric * 1.10) ORDER BY ordem LIMIT 8) t;
